catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }
    g_form.clearMessages();
    var choice = newValue.toLowerCase();
    var msg = '';

    if (choice == 'laptop') {
        msg = 'Keep the laptop secure and return it with its charger.';
    } else if (choice == 'desktop') {
        msg = 'Return the desktop tower, power cable, and peripherals.';
    } else if (choice == 'monitor') {
        msg = 'Return the monitor with all supplied cables and accessories.';
    } else if (choice == 'mobile') {
        msg = 'Protect the mobile device and return it with its charger and accessories.';
    }
    if (msg != '') {
        g_form.showFieldMsg('equipment_type', msg, 'info');
    }
}
